public async Task<DropdownDataResult<UserDto>> GetItemsAsync(
    DropdownSearchRequest request, CancellationToken ct)
{
    var query = _db.Users
        .Where(u => u.Name.Contains(request.SearchText))
        .Skip((request.Page - 1) * request.PageSize)
        .Take(request.PageSize);

    var total = await query.CountAsync(ct);
    var items = await query.ToListAsync(ct);

    return DropdownDataResult<UserDto>.WithItems(items, total);
}
